import { buildFallbackDraft, generateDailyCreatorPipeline, DraftPayload } from './geminiService';

// In-memory store for autonomous proactive drafts generated by background scanner
const proactiveStore: DraftPayload[] = [];
let scanTimer: NodeJS.Timeout | null = null;
let scanCycleCount = 0;

// Proactive Scenarios rotated by background research team
const PROACTIVE_SCENARIOS = [
  { prompt: 'Jadwal rutin broadcast WA ke 47+ PAUD sinkronisasi Dapodik dan BOP', staff: 'dewi' },
  { prompt: 'Deteksi fluktuasi kurva KMS balita & audit stunting di 3 desa dampingan', staff: 'dr_ai' },
  { prompt: 'Riset kendala operator PAUD dalam ekspor formulir Dikdasmen', staff: 'arka' },
  { prompt: 'Panduan 3 langkah mudah catat timbangan KMS untuk kader sepuh', staff: 'budi' },
  { prompt: 'Draf surat salam perkenalan digitalisasi posyandu desa ke Kepala Desa', staff: 'sari' },
  { prompt: 'Riset topik audio trending TikTok untuk drama edukasi sekolah', staff: 'trendy' },
  { prompt: 'Draf caption dan 8 tagar viral FYP untuk video fitur siput.id', staff: 'clipper' },
  { prompt: 'Artikel edukasi stop bikin kuitansi SPP manual untuk kepala sekolah PAUD', staff: 'lisa' },
];

/**
 * 06.00 AM Autonomous Daily Routine for Divisi Content Creator
 */
export async function runDailyCreatorRoutine(customTopic?: string): Promise<DraftPayload> {
  console.log('[Content Creator 06:00 AM] Siklus otomatis harian Trendy, Script-AI, dan Clipper aktif.');
  const report = await generateDailyCreatorPipeline(customTopic);
  proactiveStore.unshift(report);
  return report;
}

/**
 * Executes an autonomous proactive research cycle
 */
export function runAutonomousScanCycle(): DraftPayload {
  const scenarioIndex = scanCycleCount % PROACTIVE_SCENARIOS.length;
  const scenario = PROACTIVE_SCENARIOS[scenarioIndex];
  scanCycleCount++;

  console.log(`[Autonomous Scanner] Tim riset mendeteksi isu baru: "${scenario.prompt}" (Staf: ${scenario.staff})`);
  const draft = buildFallbackDraft(scenario.prompt, scenario.staff);
  draft.isProactive = true;

  // Prepend to store (max 30 items)
  proactiveStore.unshift(draft);
  if (proactiveStore.length > 30) {
    proactiveStore.pop();
  }

  return draft;
}

/**
 * Initializes the background Cron/Interval task
 */
export function startProactiveScanner(intervalMs = 45000): void {
  if (scanTimer) {
    clearInterval(scanTimer);
  }

  console.log(`[Autonomous Scanner] Background Cron Scanner aktif (Interval: ${intervalMs / 1000}s).`);

  // Initial immediate pulse: 06:00 AM Creator routine + research findings
  if (proactiveStore.length === 0) {
    runDailyCreatorRoutine();
    runAutonomousScanCycle();
    runAutonomousScanCycle();
  }

  // Periodic autonomous run
  scanTimer = setInterval(() => {
    try {
      runAutonomousScanCycle();
    } catch (err) {
      console.error('[Autonomous Scanner] Error in scanner cycle:', err);
    }
  }, intervalMs);
}

/**
 * Returns all proactive drafts collected in store
 */
export function getProactiveDrafts(): DraftPayload[] {
  return [...proactiveStore];
}

/**
 * Manually triggers a batch scan across the 3 divisions
 */
export function triggerManualProactiveBatch(): DraftPayload[] {
  const paud = buildFallbackDraft('Jadwal rutin broadcast WA ke 47+ PAUD sinkronisasi Dapodik', 'dewi');
  const posyandu = buildFallbackDraft('Deteksi anomali stunting dan alur KMS balita desa', 'dr_ai');
  const creator = buildFallbackDraft('Naskah video drama pendek viral 25 detik hook kuat guru PAUD', 'script_ai');

  paud.isProactive = true;
  posyandu.isProactive = true;
  creator.isProactive = true;

  proactiveStore.unshift(paud, posyandu, creator);
  return [paud, posyandu, creator];
}
